     expect:{label:'5 段', keys:['5段','5个间隔','段数']},
     confuse:[{label:'把段数当盆数', keys:['5盆'], reply:'“{hit}”是段数，不是盆数。两端都放时，盆数还要再加 1。'}],
     idk:'20 ÷ 4 等于几段？',
     off:'“{hit}”还不是段数。',
     retry:'20 ÷ 4 = 5 段。',
     hint:'4 米一段，20 米里有几个 4 米？',
     l4:'我给你半步：分成 5 段。',
